  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Tasimelteon, the closest structural analogue with a propanamide and dihydrobenzofuran system, has an absolute bioavailability of about 38% in humans, which would support high if directly transferred; however, its cyclopropane-containing scaffold is metabolically distinct from the query's fused indeno-furan system.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "Darifenacin, which shares the dihydrobenzofuran/ether motif, has a mean absolute bioavailability of 19% for its 15 mg ER formulation in CYP2D6 extensive metabolizers, directly supporting F below 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "MK-458, a fused-ring ether-containing drug, has an absolute oral bioavailability of about 4.1% in patients, demonstrating that lipophilic fused-ring ether scaffolds can undergo extensive first-pass metabolism and fall well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Eliglustat, a lipophilic amide/ether with a similar non-basic amide feature, has an absolute bioavailability of about 8.6% in a PBPK simulation, providing additional support for low bioavailability in this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic, non-basic propanamide with a fused indeno-furan scaffold. Although the closest analogue tasimelteon has F≈38%, its cyclopropane-benzofuran scaffold is metabolically less labile than the query's fused indane system. Direct absolute-bioavailability measurements for darifenacin (19%) and MK-458 (~4–5%), which share dihydrobenzofuran/ether and fused-ring motifs, show that such scaffolds can undergo extensive first-pass metabolism and fall below 20%. The high-F analogues are structurally more distant and mostly contain basic amines or prodrug features. Therefore, low is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule; the closest analogue (tasimelteon) is high, so the low prediction relies on lower-similarity analogues and structural reasoning about first-pass metabolism.",
    "Formulation and dose effects can shift borderline values (e.g., darifenacin 19% vs 25%), adding uncertainty to the threshold decision."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

